 function renderShop(){let root=$('shop-items');root.innerHTML='';for(let item of products){let owned=state.gear[item.id];let row=document.createElement('div');row.className='shop-item';row.innerHTML=`<div class="item-icon">${item.icon}</div><div><b>${item.name}${owned?' ✓':''}</b><small>${item.desc}</small></div><button class="buy-button" ${owned||state.cash<item.price?'disabled':''}>${owned?'OWNED':'$'+item.price}</button>`;row.querySelector('button').onclick=()=>{if(owned)return;if(state.cash<item.price){toast('NOT ENOUGH FUNDS · SELL YOUR FIELD ROLL');return}state.cash-=item.price;state.gear[item.id]=true;toast(`${item.name.toUpperCase()} ADDED TO YOUR KIT`);refresh()};root.append(row)}}
